const fs = require("fs");
const path = require("path");

function walk(dir) {
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (e) { return; }
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (["proc", "sys", "dev", "lost+found"].includes(entry.name)) continue;
      walk(full);
    } else if (entry.isFile() && (entry.name.endsWith(".json") || entry.name.endsWith(".js") || entry.name.endsWith(".ts") || entry.name.endsWith(".md"))) {
      try {
        const c = fs.readFileSync(full, "utf8");
        if (c.includes("withdrawalsToEthereumAreInstant") && full !== "/work/config.json") {
          console.log("Found in:", full);
        }
      } catch (e) {}
    }
  }
}
